//! Reference vectors generated by colour-science (tools/gen_vectors.py) and by
//! OpenColorIO's built-in ACES studio config (what AE's OCIO engine uses).
//! Acceptance (task book): error < 1e-4 against colour-science.

use bae_color::{TransferFunction, builtin};
use serde_json::Value;

const DATA: &str = include_str!("data/colour_vectors.json");

fn curve(id: &str) -> TransferFunction {
    match id {
        "srgb" => TransferFunction::Srgb,
        "rec709" => TransferFunction::Rec709,
        "gamma2.2" => TransferFunction::Gamma(2.2),
        "gamma2.4" => TransferFunction::Gamma(2.4),
        "pq" => TransferFunction::Pq,
        "hlg" => TransferFunction::Hlg,
        "acescc" => TransferFunction::AcesCc,
        "acescct" => TransferFunction::AcesCct,
        "slog3" => TransferFunction::SLog3,
        "logc3" => TransferFunction::LogC3,
        "logc4" => TransferFunction::LogC4,
        "vlog" => TransferFunction::VLog,
        "clog3" => TransferFunction::CanonLog3,
        "linear" => TransferFunction::Linear,
        other => panic!("unknown curve {other}"),
    }
}

fn floats(v: &Value) -> Vec<f64> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|x| x.as_f64().unwrap())
        .collect()
}

fn rel(a: f64, b: f64) -> f64 {
    (a - b).abs() / b.abs().max(1.0)
}

#[test]
fn curves_match_colour_science() {
    let data: Value = serde_json::from_str(DATA).unwrap();
    let mut worst = 0.0f64;
    for (id, c) in data["curves"].as_object().unwrap() {
        let tf = curve(id);
        let mut curve_worst = 0.0f64;
        let enc = floats(&c["encoded"]);
        let lin = floats(&c["linear"]);
        for (e, l) in enc.iter().zip(&lin) {
            let d = rel(tf.decode(*e), *l);
            assert!(d < 1e-4, "{id} decode({e}) = {} vs {l}", tf.decode(*e));
            curve_worst = curve_worst.max(d);
            // ACEScc clamps below its toe; encode is only defined on the image.
            if tf != TransferFunction::AcesCc || *l > 0.0 {
                let d = rel(tf.encode(*l), *e);
                assert!(d < 1e-4, "{id} encode({l}) = {} vs {e}", tf.encode(*l));
                curve_worst = curve_worst.max(d);
            }
        }
        eprintln!("  {id:<10} {curve_worst:.2e}");
        worst = worst.max(curve_worst);
    }
    eprintln!("curves: max error vs colour-science {worst:.2e}");
}

#[test]
fn conversions_match_colour_science() {
    let data: Value = serde_json::from_str(DATA).unwrap();
    let mut worst = 0.0f64;
    for case in data["conversions"].as_array().unwrap() {
        let src = builtin::by_id(case["src"].as_str().unwrap()).unwrap();
        let dst = builtin::by_id(case["dst"].as_str().unwrap()).unwrap();
        let rgb = floats(&case["rgb"]);
        let expected = floats(&case["out"]);
        let got = src
            .transform_to(&dst)
            .unwrap()
            .apply_f64([rgb[0], rgb[1], rgb[2]]);
        for c in 0..3 {
            let d = rel(got[c], expected[c]);
            assert!(
                d < 1e-4,
                "{} -> {} {rgb:?}: {got:?} vs {expected:?}",
                src.id,
                dst.id
            );
            worst = worst.max(d);
        }
    }
    eprintln!("conversions: max error vs colour-science {worst:.2e}");
}

#[test]
fn conversions_match_ocio_aces_config() {
    let data: Value = serde_json::from_str(DATA).unwrap();
    let Some(cases) = data["ocio"].as_array() else {
        return;
    };
    let mut worst: Vec<(f64, String)> = Vec::new();
    for case in cases {
        let src = builtin::by_id(case["src"].as_str().unwrap()).unwrap();
        let dst = builtin::by_id(case["dst"].as_str().unwrap()).unwrap();
        let rgb = floats(&case["rgb"]);
        let expected = floats(&case["out"]);
        let got = src
            .transform_to(&dst)
            .unwrap()
            .apply_f64([rgb[0], rgb[1], rgb[2]]);
        let d = (0..3).map(|c| rel(got[c], expected[c])).fold(0.0, f64::max);
        let key = format!("{} -> {}", src.id, dst.id);
        match worst.iter_mut().find(|(_, k)| *k == key) {
            Some(w) => w.0 = w.0.max(d),
            None => worst.push((d, key)),
        }
    }
    eprintln!("vs OCIO {}:", data["ocio_config"]);
    for (d, k) in &worst {
        eprintln!("  {k:<40} {d:.2e}");
    }
    // OCIO evaluates in f32 and its built-ins round some constants; 1e-4 is the
    // acceptance bound. Canon is the exception (see the PR notes).
    for (d, k) in &worst {
        assert!(*d < 1e-4, "{k}: {d:e}");
    }
}
